ND profile IS NULL;
UPDATE companies SET description='WireNut Home Services is based in Colorado Springs, Colorado, and has operated since 2004. The company provides electrical, heating, cooling, plumbing, and drain-clearing services to residential customers across Southern Colorado, including the Denver metro area, Pueblo County, and Boulder County. Ownership structure and founder names are not disclosed in the source material.

The business fields a team of licensed technicians with over 200 years of combined experience across HVAC, plumbing, and electrical trades. It reports more than 65,000 customer reviews and serves a broad footprint that spans Colorado Springs neighborhoods such as Briargate, Cimarron Hills, and Flying Horse, as well as communities in Boulder, Castle Rock, Denver, and Pueblo. Services range from emergency electrical repairs and air-conditioner diagnostics to furnace part replacement and drain clearing.

The customer base consists almost entirely of homeowners seeking same-day or scheduled maintenance, repair, and installation work. The company highlights residential HVAC, plumbing, and electrical systems as its core focus, with no indication of commercial or industrial contracts in the provided content.

WireNut emphasizes a "No Surprises Promise" that includes upfront pricing, 30-minute arrival notices, background-checked technicians, and same-day repairs when requested by 2 p.m. A lifetime workmanship warranty covers installation quality, and a risk-free guarantee offers repair or refund if an installed product underperforms in its first year. Financing is available through a Greensky partnership.', certifications=ARRAY['Best Workplaces Award (11-time recipient)','Voted Best of the Best (8-time winner)']::text[], profile='{"capabilities": ["Electrical repair and installation", "HVAC repair, maintenance, and installation", "Plumbing repair and installation", "Drain clearing", "Emergency electrical services", "Air conditioner diagnostics and repair", "Furnace repair and part replacement", "Annual home protection plan inspections"], "industries": ["Residential home services", "Home maintenance and repair"], "materials": [], "equipment": [], "volume": "", "lead_time": "Same-day repairs available for requests by 2 p.m.", "tolerances": "", "built_on": ["Lifetime workmanship warranty on all installations", "Risk-free guarantee: repair or refund if product underperforms in first year", "Upfront pricing with no hidden fees", "Same-day repairs available for requests by 2 p.m.", "30-minute arrival notice before technician dispatch"], "facts_used": ["Founded 2004 -> db", "Headquarters Colorado Springs, Colorado -> db", "Services: electrical, HVAC, plumbing, drain clearing -> /", "200+ years combined technician experience -> /", "65,000+ happy reviews -> /", "BBB Excellence in Customer Service Award 10 times -> /", "Best Workplaces Award 11-time recipient -> /", "Voted Best of the Best 8-time winner -> /", "Lifetime workmanship guarantee -> /", "Risk-free guarantee (first-year product underperformance) -> /", "Upfront pricing, 30-minute arrival notice, background-checked technicians, same-day repairs by 2pm -> /", "Financing through Greensky -> /", "Service areas listed (Colorado Springs, Boulder, Castle Rock, Denver, Pueblo) -> /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "From your home needs work, you don''t call five different companies. You call us. From heating and cooling to plumbing, drains, and electrical, we do it all", "founded_year": "2004", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='wirenut-home-services' AND approved AND profile IS NULL;
UPDATE companies SET description='Wiring Products was founded in 2004 in Sparks, Nevada, as a family-owned business focused on supplying 12-volt and automotive electrical parts. The company began with the goal of offering quality components at competitive prices, with an emphasis on domestic manufacturing.

The company produces a broad line of automotive electrical supplies, including automotive wire, battery cable, circuit breakers, copper lugs and eyelets, fuse holders and fuses, heat shrink tubing, molded trailer connectors, flashers and solenoids, and wire terminals. Many of these products are manufactured at its U.S. facility, though the company does not disclose facility size, headcount, or production volumes.

Wiring Products serves the automotive, marine, solar, RV and trailer, commercial, and industrial sectors.

